78	    // while earlier waits are still pending lets one of those waits resolve against a later record,
79	    // which makes the wait depend on the very stream it is blocking: a circular wait. Creating them
80	    // here is depth-safe, since a wait captures the dependency at call time and destroy defers.
81	    //
82	    // ONE STREAM for the remote copies, since they all leave through the same egress and separate
83	    // streams would only make them contend. This rank's OWN share crosses no link, so it can run
84	    // alongside them on the caller's stream -- hence the separate emit below. Peers are visited in
85	    // XOR-shift order, which pairs ranks up without coordination.
86	    const Event ready(cudaEventDisableTiming);
87	    ULYSSES_CUDA_CHECK(cudaEventRecord(ready, stream));
88	
89	    auto emit = [&](int p, cudaStream_t on) {
90	        for (const CopyOp& op : plan.ops) {
91	            if (op.peer == p) {
92	                issue_copy(reinterpret_cast<uint8_t*>(peer_ptrs[p]) + op.dst_offset, src_bytes + op.src_offset, op, on);
93	            }
94	        }
