98	    // Fault injection (see set_ce_fault): hold the payload back so the flag cannot be behind it.
99	    if (g_fault_delay_us > 0) {
100	        ULYSSES_CUDA_CHECK(cudaLaunchHostFunc(xfer, delay_payload, reinterpret_cast<void*>(g_fault_delay_us)));
101	    }
102	    for (int k = 1; k < ws; ++k) {
103	        const int peer = rank ^ k;
104	        if (peer < ws) {
105	            emit(peer, xfer);
106	        }
107	    }
108	    // XOR only enumerates every peer when ws is a power of two; sweep for any it missed.
109	    if ((ws & (ws - 1)) != 0) {
110	        for (int p = 0; p < ws; ++p) {
111	            if (p != rank && (p ^ rank) >= ws) {
